SET TIME ZONE 'UTC';
CREATE TABLE runtime_values (id INTEGER, label TEXT, seconds NUMERIC, occurred TIMESTAMPTZ, amount NUMERIC);
INSERT INTO runtime_values VALUES (1, 'Alpha_1', -1.25, '2024-02-29 23:59:59.999999+00', -1.01), (2, 'beta%2', 0.25, '2024-03-01 00:01:00+00', 2.999), (3, NULL, NULL, NULL, NULL), (4, 'ALPHA_3', 946684800.000001, '2024-03-01 12:00:00+00', -0.001);
SELECT id, to_timestamp(seconds), floor(amount), floor(id), floor(amount::double precision) FROM runtime_values ORDER BY id;
SELECT to_timestamp(-0.0000005), to_timestamp(0.0000005), to_timestamp(946684800.0000005), to_timestamp('infinity'::double precision), to_timestamp('-infinity'::double precision);
SELECT to_char('2024-02-29 23:59:59.123456'::timestamp, 'YYYY-MM-DD"T"HH24:MI:SS.MS US TZH:TZM OF'), to_char('2000-01-01'::date, 'YYYY-MM-DD'), to_char('infinity'::timestamp, 'YYYY'), to_char(NULL::timestamp, 'YYYY'), to_char('2000-01-01'::timestamp, '');
SELECT id, date_trunc('day', occurred), to_char(occurred, 'YYYY-MM-DD HH24:MI:SS.US OF') FROM runtime_values ORDER BY id;
SELECT date_trunc('week', '2021-01-01'::timestamp), date_trunc('quarter', '2024-05-31'::timestamp), date_trunc('year', '2024-02-29'::timestamp), date_trunc('hour', '2024-11-03 05:30:00+00'::timestamptz, 'America/New_York');
SELECT date_trunc('day', '2024-03-10 18:00:00+00'::timestamptz, 'America/New_York'), date_trunc('day', '2024-11-03 18:00:00+00'::timestamptz, 'America/New_York');
SELECT '2024-03-10 02:30:00'::timestamp AT TIME ZONE 'America/New_York', '2024-11-03 01:30:00'::timestamp AT TIME ZONE 'America/New_York', '2024-01-01 00:00:00+00'::timestamptz AT TIME ZONE 'Asia/Kolkata';
SELECT '2000-01-01'::timestamp AT TIME ZONE '+03:00', '2000-01-01'::timestamp AT TIME ZONE 'UTC-05:30', '2000-01-01'::date AT TIME ZONE 'UTC', NULL::timestamp AT TIME ZONE 'UTC', 'infinity'::timestamp AT TIME ZONE 'unknown_zone';
SELECT id, label LIKE 'Alpha%', label ILIKE 'alpha%', label NOT LIKE '%2', label NOT ILIKE '%3', label LIKE '%!_%' ESCAPE '!' FROM runtime_values ORDER BY id;
SELECT 'a_b' LIKE 'a\_b', 'a%b' LIKE 'a!%b' ESCAPE '!', 'a\b' LIKE 'a\b' ESCAPE '', 'éx' LIKE '_x', 'x' LIKE 'x\', '' LIKE '%\', 'abc' LIKE '%b%', 'abcb' LIKE '%b', 'a  '::char(3) LIKE 'a';
SELECT id, label ~ '^A', label ~* '^a', label !~ '^A', label !~* '^a', regexp_like(label, '^alpha_[0-9]{1,2}$', 'i') FROM runtime_values ORDER BY id;
SELECT regexp_like('a-b', '(a|z)-[a-z]+'), regexp_like('ABC', '^abc$', 'ic'), regexp_like('ABC', '^abc$', 'ci'), 'a  '::char(3) ~ '^a$', regexp_like('a  '::char(3), '^a$');
SELECT date_trunc('month', occurred) AS month, floor(amount) AS amount, count(*), string_agg(to_char(occurred, 'DD'), ':' ORDER BY id DESC) FILTER (WHERE label ILIKE 'a%') FROM runtime_values GROUP BY date_trunc('month', occurred), floor(amount) ORDER BY month, amount;
SELECT string_agg(to_char(occurred, 'YYYY-MM-DD'), ',' ORDER BY occurred) FROM runtime_values WHERE label ~* '^alpha';
SELECT string_agg(label, ',' ORDER BY id), floor(max(amount)) FROM runtime_values WHERE false;
BEGIN;
UPDATE runtime_values SET amount = floor(amount), occurred = date_trunc('hour', to_timestamp(seconds)) WHERE label ILIKE 'alpha%' RETURNING id, amount, occurred;
ROLLBACK;
SELECT * FROM runtime_values ORDER BY id;
SELECT regexp_like('a', 'a{'), regexp_like('a{', 'a{'), regexp_like('a{q}', 'a{q}');
SELECT extract(epoch FROM ('2024-07-01'::timestamp AT TIME ZONE 'CET')), extract(epoch FROM ('2024-07-01'::timestamp AT TIME ZONE 'Europe/Paris'));
SELECT regexp_like('a', '[]a]'), regexp_like('a', '[^]a]'), regexp_like('a', '[]{256}]'), regexp_like('a', '(^)*');
SELECT to_char('2000-01-01'::timestamp, '\"YYYY\"'), to_char('2000-01-01'::timestamp, '"a\b"'), to_char('2000-01-01'::timestamp, 'YYYY\MM');
